using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Text;using System.Threading.Tasks;namespace BitmapGenerator{    class Program    {        [DllImport("gdi32.dll")]        public static extern bool BitBlt(IntPtr hdc, int x, int y, int cx, int cy, IntPtr hdcSrc, int x1, int y1, uint rop);        static void Main(string[] args)        {            ControlToPNG(1920, 1080, IntPtr.Zero, @"C:\Users\User\Desktop\Output.png");        }        static void ControlToPNG(int controlWidth, int controlHeight, IntPtr controlHandle, string path)        {            using (var fileStream = File.Create(path))                ControlToPNG(controlWidth, controlHeight, controlHandle, fileStream);        }        static void ControlToPNG(int controlWidth, int controlHeight, IntPtr controlHandle, Stream stream)        {            using (var bitmap = new Bitmap(controlWidth, controlHeight))            using (var destinationGraphics = Graphics.FromImage(bitmap))            using (var sourceGraphics = Graphics.FromHwnd(controlHandle))            {                IntPtr destinationHandle = IntPtr.Zero;                IntPtr sourceHandle = IntPtr.Zero;                try                {                    destinationHandle = destinationGraphics.GetHdc();                    sourceHandle = sourceGraphics.GetHdc();                    BitBlt(destinationHandle, 0, 0, controlWidth, controlHeight, sourceHandle, 0, 0, 0xCC0020);                }                finally                {                    if (destinationHandle != IntPtr.Zero)                        destinationGraphics.ReleaseHdc(destinationHandle);                    if (sourceHandle != IntPtr.Zero)                        sourceGraphics.ReleaseHdc(sourceHandle);                }                bitmap.Save(stream, ImageFormat.Png);            }        }    }}